import * as React from 'react'

import { useControllableState } from '~/hooks/use-controllable-state'
import { cx } from '~/lib/cx'
import styles from './segmented-control.module.scss'

export type SegmentedSize = 'sm' | 'default'

export type SegmentedOption<T extends string> = {
  value: T
  label: React.ReactNode
  icon?: React.ReactNode
  disabled?: boolean
}

export interface SegmentedControlProps<T extends string> {
  options: Array<SegmentedOption<T>>
  value?: T
  defaultValue?: T
  onChange?: (value: T) => void
  size?: SegmentedSize
  label?: string
  className?: string
}

export function SegmentedControl<T extends string>({
  options,
  value,
  defaultValue,
  onChange,
  size = 'default',
  label = 'View',
  className,
}: SegmentedControlProps<T>) {
  const [current, setCurrent] = useControllableState<T>({
    value,
    defaultValue: defaultValue ?? options[0]?.value,
    onChange,
  })
  const refs = React.useRef<Array<HTMLButtonElement | null>>([])

  const move = (direction: 1 | -1) => {
    const enabled = options
      .map((option, index) => ({ option, index }))
      .filter(({ option }) => !option.disabled)
    if (!enabled.length) return

    const at = enabled.findIndex(({ option }) => option.value === current)
    const next = enabled[(at + direction + enabled.length) % enabled.length]
    setCurrent(next.option.value)
    refs.current[next.index]?.focus()
  }

  return (
    <div
      role="radiogroup"
      aria-label={label}
      className={cx(styles.root, size === 'sm' && styles.sm, className)}
      onKeyDown={(event) => {
        if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
          event.preventDefault()
          move(1)
        } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
          event.preventDefault()
          move(-1)
        }
      }}
    >
      {options.map((option, index) => {
        const selected = option.value === current

        return (
          <button
            key={option.value}
            ref={(node) => {
              refs.current[index] = node
            }}
            type="button"
            role="radio"
            aria-checked={selected}
            disabled={option.disabled}
            tabIndex={selected ? 0 : -1}
            onClick={() => setCurrent(option.value)}
            className={styles.option}
          >
            {option.icon ? (
              <span className={styles.icon} aria-hidden>
                {option.icon}
              </span>
            ) : null}
            {option.label}
          </button>
        )
      })}
    </div>
  )
}

@use 'styles' as vz;

.root {
  --segment-height: #{vz.space(8)};
  --segment-padding: #{vz.space(3)};
  --segment-font: #{vz.font-size('sm')};

  display: inline-flex;
  align-items: center;
  gap: vz.space(1);
  max-width: 100%;
  padding: vz.space(1);
  overflow-x: auto;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('lg');
  background: vz.color('muted');

  @include vz.scrollbar(6px);
}

.sm {
  --segment-height: #{vz.space(7)};
  --segment-padding: #{vz.space(2.5)};
  --segment-font: #{vz.font-size('xs')};
}

.option {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  gap: vz.space(1.5);
  height: var(--segment-height);
  padding-inline: var(--segment-padding);
  border: 0;
  border-radius: vz.radius('md');
  background: transparent;
  color: vz.color('muted-foreground');
  font-size: var(--segment-font);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out'),
    box-shadow vz.duration('fast') vz.ease('out');

  @include vz.hover {
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 2px, 0.6);

  @include vz.disabled {
    opacity: 0.5;
    pointer-events: none;
  }

  @include vz.motion-reduce {
    transition: none;
  }
}

.option[aria-checked='true'] {
  background: vz.color('card');
  color: vz.color('foreground');
  box-shadow: vz.elevation(1);
}

.icon {
  display: inline-flex;
  flex: none;

  svg {
    @include vz.icon(4);
  }
}
